<script setup lang="ts">
import type{components}from'~/api/schema';import{unwrap,versionHeaders}from'~/api/client';import{displayError}from'~/utils/errors';import{formatDate,formatRupiah,statusLabel}from'~/utils/format';type Order=components['schemas']['VendorOrderPrivate'];
definePageMeta({middleware:'auth'});const api=useMarketplaceApi();const portal=usePortal();const route=useRoute();const order=ref<Order>();const pending=ref(true);const message=ref('');const operationId=ref('');
async function load(){pending.value=true;try{if(!portal.activeStore.value)await portal.loadStores();order.value=unwrap(await api.GET('/vendor/stores/{storeId}/orders/{vendorOrderId}',{params:{path:{storeId:portal.storeId.value,vendorOrderId:String(route.params.id)}},cache:'no-store'}));}catch(cause){message.value=displayError(cause).message;}finally{pending.value=false;}}
async function ready(){if(!order.value)return;try{const operation=unwrap(await api.POST('/vendor/stores/{storeId}/orders/{vendorOrderId}/ready-to-ship',{params:{path:{storeId:portal.storeId.value,vendorOrderId:order.value.id},header:{...versionHeaders(order.value.row_version),'Idempotency-Key':crypto.randomUUID()}}}));operationId.value=operation.id;}catch(cause){message.value=displayError(cause).message;}}
onMounted(()=>{void load();});useSeoMeta({title:'Detail pesanan vendor — Niaga'});
</script>
<template><main id="main-content" class="page-shell"><PortalNav area="vendor"/><ApiState :pending="pending" :empty="!pending&&!order" empty-title="Pesanan tidak ditemukan"><template v-if="order"><div class="section-heading"><div><p class="eyebrow">Pesanan vendor</p><h1>{{ order.order_number }}</h1><p>{{ formatDate(order.created_at) }}</p></div><span class="badge">{{ statusLabel(order.fulfillment_status) }}</span></div><p v-if="message" class="surface" role="status">{{ message }}</p><div class="order-detail-grid"><section class="checkout-steps"><article class="surface"><h2>Item snapshot</h2><div v-for="item in order.items" :key="item.id" class="order-item"><div><strong>{{ item.product_name }}</strong><small>{{ item.sku_code }} · {{ item.quantity }} unit</small></div><div class="money-breakdown"><span>Net {{ formatRupiah(item.line_net) }}</span><span>PPN {{ formatRupiah(item.line_vat) }}</span><strong>{{ formatRupiah(item.line_gross) }}</strong></div></div></article><article v-if="order.recipient" class="surface"><h2>Penerima</h2><strong>{{ order.recipient.recipient_name }}</strong><p>{{ order.recipient.phone }}</p><p>{{ order.recipient.street }}, {{ order.recipient.district }}, {{ order.recipient.city }} {{ order.recipient.postal_code }}</p></article><article class="surface"><h2>Dokumen transaksi</h2><DocumentUploader :vendor-order-id="order.id" :allowed-types="['INVOICE','TAX_INVOICE','OTHER']"/></article></section><aside class="surface order-summary"><h2>Keuangan</h2><div class="summary-line"><span>Total pembeli</span><strong>{{ formatRupiah(order.buyer_total) }}</strong></div><div class="summary-line"><span>Komisi</span><span>{{ formatRupiah(order.commission_amount) }}</span></div><div class="summary-line"><span>PPN komisi</span><span>{{ formatRupiah(order.commission_vat) }}</span></div><div class="summary-line"><span>PPh penjual</span><span>{{ formatRupiah(order.seller_withholding) }}</span></div><div class="summary-line summary-total"><span>Hak vendor</span><strong>{{ formatRupiah(order.payable_amount) }}</strong></div><button v-if="['UNFULFILLED','PROCESSING'].includes(order.fulfillment_status)&&!order.shipment_id" @click="ready">Siap dikirim</button><OperationStatus v-if="operationId" :operation-id="operationId" @complete="load"/><NuxtLink v-if="order.shipment_id" :to="`/vendor/pengiriman/${order.shipment_id}`">Lihat pengiriman</NuxtLink></aside></div></template></ApiState></main></template>
